// diag_val returns 1.0 on the diagonal and 0.0 elsewhere.
// The problem statement uses "int"; in Rust we choose isize as a signed integer type.
fn diag_val(i: isize, j: isize) -> f64 {
    if i == j { 1.0 } else { 0.0 }
}

// identity constructs an n x n identity matrix of f64 values.
fn identity(n: usize) -> Vec<Vec<f64>> {
    let mut mat: Vec<Vec<f64>> = Vec::with_capacity(n);

    for i in 0..n {
        let mut row = vec![0.0_f64; n];
        // Safe because i is in 0..n and row has length n.
        row[i] = 1.0_f64;
        mat.push(row);
    }

    mat
}

